<?php
/** Native variable-product/refund and owner-history checks, isolated test stores only. */
use GhoroaHat\Rewards\{DB,Settings,Membership,Wallet,Orders,Rewards,Calculator};
add_filter('pre_wp_mail','__return_true');
global $ghr_lifecycle_count;$ghr_lifecycle_count=0;
function lifecycle_check($actual,$expected,$message){global $ghr_lifecycle_count;++$ghr_lifecycle_count;if($actual!==$expected){throw new RuntimeException($message.': '.var_export($actual,true));}echo "PASS $message\n";}
$old=Settings::all();$run='life'.bin2hex(random_bytes(5));$u=wp_insert_user(array('user_login'=>$run,'user_email'=>$run.'@example.org','user_pass'=>wp_generate_password(),'role'=>'customer'));Membership::enroll($u);DB::update(DB::table('memberships'),array('email_verified_at'=>DB::now()),array('user_id'=>$u));
try{
$p=new WC_Product_Variable();$p->set_name('Variable inaugural fixture');$p->save();$v=new WC_Product_Variation();$v->set_parent_id($p->get_id());$v->set_regular_price('999');$v->set_virtual(true);$v->set_tax_status('none');$v->save();Settings::save(array('bonus_products'=>array($p->get_id()),'excluded_products'=>array(),'excluded_categories'=>array(),'seeds_bps'=>100,'trust_bonus'=>10000,'historical_rewards'=>false,'enabled'=>true,'trust_enabled'=>true,'seeds_enabled'=>true));
$o=wc_create_order(array('customer_id'=>$u));$item=$o->add_product($v,1);$o->calculate_totals();$o->save();Orders::reconcile($o->get_id());lifecycle_check(Wallet::account($u,'trust')['posted'],0,'Unpaid variable product grants no bonus');$o->payment_complete('local-fixture-success');Orders::reconcile($o->get_id());lifecycle_check(Wallet::account($u,'trust')['posted'],0,'Payment success waits for fulfillment');$o->update_status('completed');Orders::reconcile($o->get_id());lifecycle_check(Wallet::account($u,'trust')['posted'],10000,'Selected variable parent qualifies variation');lifecycle_check(Wallet::account($u,'seeds')['posted'],9,'Variable-product Seeds round down');
$refund=wc_create_refund(array('order_id'=>$o->get_id(),'amount'=>'999','reason'=>'Full native refund fixture','refund_payment'=>false,'line_items'=>array($item=>array('qty'=>1,'refund_total'=>'999','refund_tax'=>array()))));if(is_wp_error($refund)){throw new RuntimeException($refund->get_error_message());}$o=wc_get_order($o->get_id());$o->update_status('refunded');Orders::reconcile($o->get_id());lifecycle_check(Wallet::account($u,'trust')['posted'],0,'Full native refund reverses introductory grant');lifecycle_check(Wallet::account($u,'seeds')['posted'],0,'Full native refund reverses Seeds');Orders::reconcile($o->get_id());lifecycle_check(Wallet::account($u,'trust')['posted'],0,'Repeated full refund is idempotent');
$all=Wallet::history($u,'trust',1,100);lifecycle_check(count(Wallet::history($u,'trust',1,100,array('direction'=>'credit'))),1,'History credit filter');lifecycle_check(count(Wallet::history($u,'trust',1,100,array('direction'=>'debit'))),1,'History debit filter');lifecycle_check(count(Wallet::history($u,'trust',1,100,array('from'=>wp_date('Y-m-d'),'to'=>wp_date('Y-m-d')))),count($all),'History date range uses site calendar');lifecycle_check(count(Wallet::history($u,'trust',1,100,array('from'=>'2099-01-01'))),0,'History date range excludes older records');lifecycle_check(array_key_exists('expires_at',$all[0]),true,'History exposes configured lot expiry');
DB::update(DB::table('memberships'),array('status'=>'active'),array('user_id'=>$u));$def=Rewards::definition(array('name'=>'Suspension fixture','type'=>'gift','stock'=>1,'config'=>array()));$campaign=Rewards::campaign(array('name'=>$run,'month'=>wp_date('Y-m'),'category'=>'manual','definition_id'=>$def,'capacity'=>1));$box=Rewards::assign($u,$campaign,$run);Rewards::transition($u,$box,'open');DB::update(DB::table('memberships'),array('status'=>'suspended'),array('user_id'=>$u));$blocked=false;try{Rewards::transition($u,$box,'claim');}catch(DomainException $e){$blocked=true;}lifecycle_check($blocked,true,'Suspended membership cannot claim prizes');
echo "LIFECYCLE PASS: $ghr_lifecycle_count assertions\n";
}finally{update_option('ghr_settings',$old,false);}
